            let rr = foam.radius * (0.7 + (1 - alpha) * 0.3);
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x, foam.position.y, rr, 0, Math.PI * 2);
            targetCtx.fill();
        }
    }

    drawBeerDetails(targetCtx){
        targetCtx.save();

        // Rising bubbles and bright specular flecks inside the settled beer.
        for(let i=0; i<this.particles.length; i += 6){
            let p = this.particles[i];
            if(!this.isInsideGlassInterior(p.position)){
                continue;
            }
            if(i % 12 === 0){
                let bob = Math.sin(this.frame * 0.05 + i) * 2;
                let bubbleR = 1.1 + ((i * 17) % 5) * 0.4;
                targetCtx.globalAlpha = 0.5;
                targetCtx.beginPath();
                targetCtx.arc(p.position.x + bob, p.position.y - 3, bubbleR, 0, Math.PI * 2);
                targetCtx.strokeStyle = "rgba(255,247,205,0.8)";
                targetCtx.lineWidth = 1;
                targetCtx.stroke();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    drawFoamDetails(targetCtx){
        targetCtx.save();

        for(let i=0; i<this.foamParticles.length; i++){
            let foam = this.foamParticles[i];
            let alpha = Math.max(0, Math.min(1, foam.life / foam.maxLife));
            let r = foam.radius * (0.62 + (1 - alpha) * 0.2);

            // little shadow under each bubble for a creamy, dimensional head
            targetCtx.globalAlpha = 0.12 * alpha;
            targetCtx.beginPath();
            targetCtx.arc(foam.position.x + r * 0.18, foam.position.y + r * 0.28, r * 0.9, 0, Math.PI * 2);
            targetCtx.fillStyle = "#caa258";
            targetCtx.fill();

            if(i % 2 === 0){
                targetCtx.globalAlpha = 0.7 * alpha;
                targetCtx.beginPath();
                targetCtx.arc(foam.position.x - r * 0.26, foam.position.y - r * 0.3, Math.max(1, r * 0.24), 0, Math.PI * 2);
                targetCtx.fillStyle = "#ffffff";
                targetCtx.fill();
            }
        }

        targetCtx.restore();
        targetCtx.globalAlpha = 1;
    }

    /* ---------- Rendering: solid props ---------- */

    drawBack(){
        this.drawGlassBack();
        this.drawBottle();
    }

    drawFront(){
        this.drawGlassFront();
    }

    drawGlassBack(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));

        ctx.save();
        // faint cool glass body so the beer reads as sitting inside real glass
        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.closePath();
        let body = ctx.createLinearGradient(rimA.x, 0, rimB.x, 0);
        body.addColorStop(0, "rgba(214,226,224,0.30)");
        body.addColorStop(0.5, "rgba(236,243,240,0.12)");
        body.addColorStop(1, "rgba(214,226,224,0.22)");
        ctx.fillStyle = body;
        ctx.fill();
        ctx.restore();
    }

    drawGlassFront(){
        let g = this.glass;
        let topY = -g.height * 0.5;
        let bottomY = g.height * 0.5;
        let rimA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.5, topY));
        let rimB = this.glassLocalToWorld(new Vector2(g.topWidth * 0.5, topY));
        let baseA = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.5, bottomY));
        let baseB = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.5, bottomY));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        // body outline
        ctx.beginPath();
        ctx.moveTo(rimA.x, rimA.y);
        ctx.lineTo(baseA.x, baseA.y);
        ctx.lineTo(baseB.x, baseB.y);
        ctx.lineTo(rimB.x, rimB.y);
        ctx.strokeStyle = "rgba(70,82,86,0.45)";
        ctx.lineWidth = 5;
        ctx.stroke();

        // rim (front + back ellipse halves)
        let rimCenter = this.glassLocalToWorld(new Vector2(0, topY));
        ctx.beginPath();
        ctx.ellipse(rimCenter.x, rimCenter.y, g.topWidth * 0.5, 12, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(255,255,255,0.85)";
        ctx.lineWidth = 4;
        ctx.stroke();
        ctx.beginPath();
        ctx.ellipse(rimCenter.x, rimCenter.y, g.topWidth * 0.5, 12, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(90,100,104,0.30)";
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // base ellipse
        let baseCenter = this.glassLocalToWorld(new Vector2(0, bottomY));
        ctx.beginPath();
        ctx.ellipse(baseCenter.x, baseCenter.y, g.bottomWidth * 0.5, 9, this.glass.angle, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(70,82,86,0.4)";
        ctx.lineWidth = 4;
        ctx.stroke();

        // vertical highlight streaks
        let shineA = this.glassLocalToWorld(new Vector2(-g.topWidth * 0.30, topY + 22));
        let shineB = this.glassLocalToWorld(new Vector2(-g.bottomWidth * 0.26, bottomY - 30));
        DrawUtils.drawLine(shineA, shineB, "rgba(255,255,255,0.5)", 5);
        let shineC = this.glassLocalToWorld(new Vector2(g.topWidth * 0.34, topY + 30));
        let shineD = this.glassLocalToWorld(new Vector2(g.bottomWidth * 0.30, bottomY - 60));
        DrawUtils.drawLine(shineC, shineD, "rgba(255,255,255,0.28)", 3);

        ctx.restore();
    }

    drawBottle(){
        let b = this.bottle;
        let axis = b.axis;
        let normal = axis.GetNormal();
        normal.Normalize();
        let bodyCenter = Add(b.mouth, Scale(axis, b.neckLength + b.bodyLength * 0.5));

        ctx.save();
        ctx.lineJoin = "round";
        ctx.lineCap = "round";

        // --- glass body fill (brown, cylinder shading across the normal) ---
        this.traceBottlePath(ctx, 0);
        let edge0 = Add(bodyCenter, Scale(normal, -b.bodyWidth * 0.5));
        let edge1 = Add(bodyCenter, Scale(normal, b.bodyWidth * 0.5));
        let glass = ctx.createLinearGradient(edge0.x, edge0.y, edge1.x, edge1.y);
        glass.addColorStop(0.0, "#3a1f0c");
        glass.addColorStop(0.32, "#6e3c14");
        glass.addColorStop(0.5, "#8a5018");
        glass.addColorStop(0.7, "#5d3110");
        glass.addColorStop(1.0, "#2c1708");
        ctx.fillStyle = glass;
        ctx.fill();

        // beer still inside the bottle (horizontal surface)
        this.drawBottleLiquid();

        // re-stroke the silhouette so the liquid stays tucked inside the glass
        this.traceBottlePath(ctx, 0);
        ctx.strokeStyle = "rgba(20,12,5,0.55)";
        ctx.lineWidth = 3;
        ctx.stroke();

        // glass rim highlight running down one side
        let hi0 = Add(bodyCenter, Add(Scale(normal, -b.bodyWidth * 0.30), Scale(axis, -b.bodyLength * 0.42)));
        let hi1 = Add(bodyCenter, Add(Scale(normal, -b.bodyWidth * 0.30), Scale(axis, b.bodyLength * 0.30)));
        DrawUtils.drawLine(hi0, hi1, "rgba(255,210,140,0.35)", 7);

        // --- label ---
        this.drawBottleLabel(bodyCenter, axis, normal);

        // --- cap ---
        let capCenter = Add(b.mouth, Scale(axis, 7));
        this.drawOrientedCapsule(capCenter, axis, normal, 22, b.neckWidth + 8, "#caa23c", "#7a5a18");
        let capTop = Add(b.mouth, Scale(axis, -1));
        this.drawOrientedCapsule(capTop, axis, normal, 5, b.neckWidth + 4, "#e8cd72", null);

        ctx.restore();
    }

    drawBottleLiquid(){
        let fill = Math.max(0, Math.min(1, this.bottleVolumeL / this.BOTTLE_CAPACITY_L));
        if(fill <= 0.001){
            return;
        }

        // World vertical extent of the bottle interior, so the surface stays horizontal.
        let b = this.bottle;
        let bodyTopY = -b.bodyLength * 0.5;
        let bodyBotY = b.bodyLength * 0.5;
        let mouthTipY = bodyTopY - b.neckLength;
        let minY = Infinity;
        let maxY = -Infinity;
        let samples = [
